// Builds eslint/page-archetypes.json: page file -> DsPage `layout` archetype (hardening spec 7.5/R6).
// Source: the route fragments of every module (component import, path, meta.layout, roles) and the
// page file name (the page type). Heuristic, reviewable, regenerated by:
//   node scripts/codemods/page-archetypes.mjs
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

import { listFiles, ROOT } from '../lib/ds-debt-scan.mjs'

export const OUT = join(ROOT, 'eslint/page-archetypes.json')

const NAME_RULES = [
  ['dashboard', /(Dashboard|Beranda|Overview|Landing|HomePage|CommandCenter|Hub)/],
  [
    'report',
    /(Report|Laporan|Analitik|Analytics|Monitoring|Prestasi|Performance|Statistik|Insight|Kirkpatrick|Usage|Penggunaan|Leaderboard)/,
  ],
  [
    'form',
    /(Create|Edit|New|Form|Cipta|Tetapan|Settings|Profile|Profil|Register|Login|Password|Config|Import|Upload|Wizard|Invite|Reset|Verify|Bayar|Checkout)/,
  ],
  [
    'list',
    /(List|Index|Browse|Table|Senarai|Library|Bank|Directory|Inbox|Tickets|Queue|Marketplace|Catalog)/,
  ],
  ['detail', /(Detail|View|Result|Keputusan|Review|Profile)/],
]

/** Page file name -> archetype (name first, then the shell / role of its route). */
export function archetypeFor(file, meta) {
  const base = file
    .split('/')
    .pop()
    .replace(/\.vue$/, '')
  for (const [layout, re] of NAME_RULES) if (re.test(base)) return layout
  if (meta?.layout === 'user' && meta.roles === 'student') return 'learner'
  return 'detail'
}

export function buildMap() {
  const map = {}
  const routeFiles = listFiles(['src/modules'], ROOT).filter(
    (f) => /\/routes(\/[^/]+)?\.ts$/.test(f) || /\/routes\.ts$/.test(f),
  )
  for (const rf of routeFiles) {
    const text = readFileSync(join(ROOT, rf), 'utf8')
    const re = /import\(\s*'([^']+\.vue)'\s*\)/g
    let m
    while ((m = re.exec(text))) {
      const abs = join(dirname(join(ROOT, rf)), m[1])
      const page = relative(ROOT, abs).replaceAll('\\', '/')
      const before = text.slice(Math.max(0, m.index - 400), m.index)
      const after = text.slice(m.index, m.index + 700)
      const path = [...before.matchAll(/path:\s*'([^']*)'/g)].pop()?.[1]
      const layout = /layout:\s*'([\w-]+)'/.exec(after)?.[1]
      const roles = /roles(?::\s*\[([^\]]*)\])?/.exec(after)
      const student = roles?.[1] && /^\s*'student'\s*$/.test(roles[1]) ? 'student' : undefined
      map[page] = {
        layout: archetypeFor(page, { layout, roles: student }),
        route: path ?? null,
        shell: layout ?? null,
      }
    }
  }
  return Object.fromEntries(Object.entries(map).sort(([a], [b]) => (a < b ? -1 : 1)))
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  const map = buildMap()
  writeFileSync(
    OUT,
    JSON.stringify(
      {
        comment:
          'page file -> DsPage layout archetype; generated by scripts/codemods/page-archetypes.mjs',
        pages: map,
      },
      null,
      2,
    ) + '\n',
  )
  const counts = {}
  for (const v of Object.values(map)) counts[v.layout] = (counts[v.layout] ?? 0) + 1
  console.log(
    `page-archetypes: ${Object.keys(map).length} pages`,
    counts,
    fileURLToPath(pathToFileURL(OUT)),
  )
}
